# -*- coding: utf-8 -*-
"""
WhatsApp automatico a clientes con la API oficial de Meta (Cloud API):
- Nuevo backend/whatsapp_meta.py (envio de plantillas + PDF, webhook).
- Alta de clientes desde la app de iPad (quedan en el CRM como prospecto) con
  mensaje de bienvenida automatico.
- Al crear una cotizacion, mandar al cliente bienvenida + PDF por WhatsApp.
- Webhook /webhook/whatsapp-meta: estatus (entregado/leido/fallo) y las
  respuestas del cliente quedan en el historial del CRM.
- Tabla whatsapp_envios y columna cotizaciones.cliente_crm_id (se crean solas
  al arrancar).

Toca: backend/db.py, backend/app.py y crea backend/whatsapp_meta.py.
Se puede correr varias veces.

Uso: en la carpeta del repo:
    py -3 fix_whatsapp_meta.py
"""
import os
import sys

ARCHIVOS = {'backend/db.py': [['        ALTER TABLE cotizaciones ADD CONSTRAINT cotizaciones_oportunidad_id_fkey\n            FOREIGN KEY (oportunidad_id) REFERENCES crm_oportunidades(id) ON DELETE SET NULL;\n', '        ALTER TABLE cotizaciones ADD CONSTRAINT cotizaciones_oportunidad_id_fkey\n            FOREIGN KEY (oportunidad_id) REFERENCES crm_oportunidades(id) ON DELETE SET NULL;\n        -- Ventas (app de iPad / Checador): la cotización puede quedar ligada\n        -- directo a un cliente del CRM (además de por oportunidad), y cada\n        -- WhatsApp automático que se manda por la API de Meta queda aquí con\n        -- su estatus (enviado / entregado / leído / falló).\n        ALTER TABLE cotizaciones ADD COLUMN IF NOT EXISTS cliente_crm_id INTEGER REFERENCES crm_clientes(id) ON DELETE SET NULL;\n        CREATE TABLE IF NOT EXISTS whatsapp_envios (\n            id SERIAL PRIMARY KEY,\n            empresa_id INTEGER NOT NULL REFERENCES empresas(id),\n            cliente_crm_id INTEGER REFERENCES crm_clientes(id) ON DELETE SET NULL,\n            cotizacion_id INTEGER REFERENCES cotizaciones(id) ON DELETE SET NULL,\n            telefono TEXT NOT NULL,\n            tipo TEXT NOT NULL,\n            wamid TEXT,\n            estatus TEXT NOT NULL,\n            error TEXT,\n            usuario_id INTEGER REFERENCES users(id),\n            creado_en TEXT NOT NULL,\n            actualizado_en TEXT NOT NULL\n        );\n        CREATE INDEX IF NOT EXISTS idx_whatsapp_envios_wamid ON whatsapp_envios(wamid);\n'], ['# ---- CRM de ventas: clientes/prospectos ----\n', '# ---- Ventas: clientes desde la app de iPad + WhatsApp automático (Meta) ----\n\ndef _solo_digitos_sql(columna):\n    return f"right(regexp_replace(coalesce({columna}, \'\'), \'[^0-9]\', \'\', \'g\'), 10)"\n\n\ndef buscar_cliente_crm_por_ultimos10(empresa_id, ultimos10):\n    """Busca un cliente del CRM por los últimos 10 dígitos del teléfono (sin\n    importar si se guardó con espacios, guiones o con +52)."""\n    if not ultimos10 or len(ultimos10) < 10:\n        return None\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute(\n        f"SELECT * FROM crm_clientes WHERE empresa_id = %s AND {_solo_digitos_sql(\'telefono\')} = %s ORDER BY id LIMIT 1",\n        (empresa_id, ultimos10),\n    )\n    row = cur.fetchone()\n    cur.close(); conn.close()\n    return dict(row) if row else None\n\n\ndef listar_clientes_ventas(empresa_id, buscar=None, solo_creados_por=None, limite=60):\n    conn = get_connection()\n    cur = conn.cursor()\n    condiciones = ["c.empresa_id = %s"]\n    valores = [empresa_id]\n    if solo_creados_por:\n        condiciones.append("c.creado_por_id = %s"); valores.append(solo_creados_por)\n    for palabra in (buscar or "").split():\n        condiciones.append("(c.nombre ILIKE %s OR c.telefono ILIKE %s OR c.email ILIKE %s)")\n        comodin = f"%{palabra}%"\n        valores += [comodin, comodin, comodin]\n    valores.append(limite)\n    cur.execute(\n        f"""SELECT c.id, c.nombre, c.tipo, c.telefono, c.email, c.giro, c.notas, c.creado_en,\n                   u.nombre_completo AS creado_por_nombre,\n                   (SELECT w.estatus FROM whatsapp_envios w WHERE w.cliente_crm_id = c.id ORDER BY w.id DESC LIMIT 1) AS whatsapp_estatus,\n                   (SELECT w.creado_en FROM whatsapp_envios w WHERE w.cliente_crm_id = c.id ORDER BY w.id DESC LIMIT 1) AS whatsapp_fecha,\n                   (SELECT COUNT(*) FROM cotizaciones q WHERE q.cliente_crm_id = c.id) AS cotizaciones\n            FROM crm_clientes c\n            LEFT JOIN users u ON u.id = c.creado_por_id\n            WHERE {\' AND \'.join(condiciones)}\n            ORDER BY c.id DESC\n            LIMIT %s""",\n        valores,\n    )\n    rows = [dict(r) for r in cur.fetchall()]\n    cur.close(); conn.close()\n    return rows\n\n\ndef vincular_cotizacion_cliente_crm(empresa_id, cotizacion_id, cliente_id):\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute(\n        """UPDATE cotizaciones SET cliente_crm_id = %s\n           WHERE id = %s AND empresa_id = %s\n             AND EXISTS (SELECT 1 FROM crm_clientes WHERE id = %s AND empresa_id = %s)""",\n        (cliente_id, cotizacion_id, empresa_id, cliente_id, empresa_id),\n    )\n    conn.commit()\n    cur.close(); conn.close()\n\n\ndef registrar_envio_whatsapp(empresa_id, tipo, telefono, estatus, usuario_id=None, cliente_crm_id=None,\n                             cotizacion_id=None, wamid=None, error=None):\n    conn = get_connection()\n    cur = conn.cursor()\n    ts = ahora().isoformat(timespec="seconds")\n    cur.execute(\n        """INSERT INTO whatsapp_envios (empresa_id, cliente_crm_id, cotizacion_id, telefono, tipo, wamid,\n                                        estatus, error, usuario_id, creado_en, actualizado_en)\n           VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s) RETURNING id""",\n        (empresa_id, cliente_crm_id, cotizacion_id, telefono, tipo, wamid, estatus, error, usuario_id, ts, ts),\n    )\n    envio_id = cur.fetchone()["id"]\n    conn.commit()\n    cur.close(); conn.close()\n    return envio_id\n\n\n_ORDEN_ESTATUS_WHATSAPP = {"enviando": 0, "error": 0, "sent": 1, "delivered": 2, "read": 3, "failed": 4}\n\n\ndef actualizar_envio_whatsapp_por_wamid(wamid, estatus, error=None):\n    """Aviso del webhook de Meta. No regresa un estatus para atrás (a veces\n    \'delivered\' llega después de \'read\')."""\n    if not wamid or not estatus:\n        return None\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute("SELECT id, estatus, empresa_id, cliente_crm_id, cotizacion_id FROM whatsapp_envios WHERE wamid = %s", (wamid,))\n    row = cur.fetchone()\n    if not row:\n        cur.close(); conn.close()\n        return None\n    actual = _ORDEN_ESTATUS_WHATSAPP.get(row["estatus"], 0)\n    nuevo = _ORDEN_ESTATUS_WHATSAPP.get(estatus, 0)\n    if nuevo >= actual:\n        cur.execute("UPDATE whatsapp_envios SET estatus = %s, error = COALESCE(%s, error), actualizado_en = %s WHERE id = %s",\n                    (estatus, error, ahora().isoformat(timespec="seconds"), row["id"]))\n        conn.commit()\n    resultado = dict(row)\n    cur.close(); conn.close()\n    return resultado\n\n\ndef empresa_de_ultimo_envio_whatsapp(ultimos10):\n    """Para mensajes que el cliente nos contesta: a qué empresa/cliente le\n    escribimos por última vez a ese número."""\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute(\n        f"SELECT empresa_id, cliente_crm_id FROM whatsapp_envios WHERE {_solo_digitos_sql(\'telefono\')} = %s ORDER BY id DESC LIMIT 1",\n        (ultimos10,),\n    )\n    row = cur.fetchone()\n    cur.close(); conn.close()\n    return dict(row) if row else None\n\n\ndef ultimo_envio_whatsapp_cotizacion(cotizacion_id):\n    conn = get_connection()\n    cur = conn.cursor()\n    cur.execute("SELECT estatus, error, creado_en FROM whatsapp_envios WHERE cotizacion_id = %s ORDER BY id DESC LIMIT 1",\n                (cotizacion_id,))\n    row = cur.fetchone()\n    cur.close(); conn.close()\n    return dict(row) if row else None\n\n\n# ---- CRM de ventas: clientes/prospectos ----\n']], 'backend/app.py': [['import r2\n', 'import r2\nimport whatsapp_meta\n'], ['    imagen_visual: Optional[str] = None\n    config_visual: Optional[dict] = None\n\n\nclass EstatusCotizacionIn', '    imagen_visual: Optional[str] = None\n    config_visual: Optional[dict] = None\n    # Cliente del CRM elegido en la app de ventas (opcional).\n    cliente_crm_id: Optional[int] = None\n\n\nclass EstatusCotizacionIn'], ['        resultado["tiene_imagen_visual"] = True\n    return resultado\n\n\n@app.put("/api/cotizaciones/{cotizacion_id}")', '        resultado["tiene_imagen_visual"] = True\n    if payload.cliente_crm_id:\n        db.vincular_cotizacion_cliente_crm(usuario["empresa_id"], resultado["id"], payload.cliente_crm_id)\n        resultado["cliente_crm_id"] = payload.cliente_crm_id\n    return resultado\n\n\n# ---- Ventas: clientes desde la app de iPad + WhatsApp automático (API de Meta) ----\n# Cualquiera con acceso al Checador de precio puede dar de alta clientes\n# (quedan en el CRM como prospecto). Un vendedor sin permiso de CRM solo ve\n# los clientes que él mismo dio de alta; admin o quien tenga CRM ve todos.\n\nclass ClienteVentasIn(BaseModel):\n    nombre: str = Field(min_length=1, max_length=200)\n    telefono: str = Field(min_length=7, max_length=30)\n    email: Optional[str] = None\n    giro: Optional[str] = None\n    notas: Optional[str] = None\n    enviar_whatsapp: bool = True\n\n\ndef _ve_todos_los_clientes(usuario: dict) -> bool:\n    return usuario["rol"] == "admin" or bool(usuario.get("acceso_crm"))\n\n\ndef _nombre_empresa(empresa_id) -> str:\n    empresa = db.obtener_empresa(empresa_id) or {}\n    return empresa.get("nombre") or "nuestra empresa"\n\n\ndef _whatsapp_bienvenida(usuario: dict, cliente: dict) -> dict:\n    """Manda la plantilla de bienvenida y deja registro (tabla + historial\n    del CRM). Nunca truena: regresa {ok, estatus, error}."""\n    empresa_id = usuario["empresa_id"]\n    telefono = cliente.get("telefono") or ""\n    try:\n        wamid = whatsapp_meta.enviar_bienvenida(telefono, cliente["nombre"], _nombre_empresa(empresa_id),\n                                                usuario.get("nombre") or "tu asesor")\n    except whatsapp_meta.ErrorWhatsApp as e:\n        db.registrar_envio_whatsapp(empresa_id, "bienvenida", telefono, "error", usuario["id"], cliente["id"], error=str(e))\n        return {"ok": False, "estatus": "error", "error": str(e)}\n    db.registrar_envio_whatsapp(empresa_id, "bienvenida", telefono, "sent", usuario["id"], cliente["id"], wamid=wamid)\n    try:\n        db.crear_interaccion_crm(empresa_id, cliente["id"], None, "whatsapp",\n                                 "WhatsApp automático: mensaje de bienvenida", usuario["id"])\n    except Exception as e:\n        print(f"[whatsapp_meta] no se pudo registrar la interacción: {e}")\n    return {"ok": True, "estatus": "sent", "error": None}\n\n\n@app.get("/api/ventas/whatsapp/estado")\ndef api_ventas_whatsapp_estado(usuario: dict = Depends(requiere_ver_checador_precio)):\n    return {"configurado": whatsapp_meta.configurado()}\n\n\n@app.get("/api/ventas/clientes")\ndef api_ventas_listar_clientes(buscar: Optional[str] = None, usuario: dict = Depends(requiere_ver_checador_precio)):\n    solo = None if _ve_todos_los_clientes(usuario) else usuario["id"]\n    return db.listar_clientes_ventas(usuario["empresa_id"], buscar, solo)\n\n\n@app.post("/api/ventas/clientes")\ndef api_ventas_crear_cliente(payload: ClienteVentasIn, usuario: dict = Depends(requiere_ver_checador_precio)):\n    empresa_id = usuario["empresa_id"]\n    if not whatsapp_meta.normalizar_telefono(payload.telefono):\n        raise HTTPException(status_code=400, detail="El teléfono no es válido — captura los 10 dígitos.")\n    existente = db.buscar_cliente_crm_por_ultimos10(empresa_id, whatsapp_meta.ultimos_10(payload.telefono))\n    if existente:\n        return {"cliente": existente, "ya_existia": True, "whatsapp": None}\n    cliente_id = db.crear_cliente_crm(\n        empresa_id, " ".join(payload.nombre.split()), "prospecto", payload.telefono.strip(),\n        (payload.email or "").strip() or None, None, (payload.notas or "").strip() or None, usuario["id"],\n        giro=(payload.giro or "").strip() or None,\n    )\n    cliente = db.obtener_cliente_crm(empresa_id, cliente_id)\n    whatsapp = None\n    if payload.enviar_whatsapp:\n        whatsapp = _whatsapp_bienvenida(usuario, cliente) if whatsapp_meta.configurado() else \\\n            {"ok": False, "estatus": "error", "error": "WhatsApp Business (Meta) todavía no está configurado en el servidor."}\n    return {"cliente": cliente, "ya_existia": False, "whatsapp": whatsapp}\n\n\n@app.post("/api/ventas/clientes/{cliente_id}/whatsapp-bienvenida")\ndef api_ventas_reenviar_bienvenida(cliente_id: int, usuario: dict = Depends(requiere_ver_checador_precio)):\n    cliente = db.obtener_cliente_crm(usuario["empresa_id"], cliente_id)\n    if not cliente or (not _ve_todos_los_clientes(usuario) and cliente.get("creado_por_id") != usuario["id"]):\n        raise HTTPException(status_code=404, detail="Cliente no encontrado")\n    if not whatsapp_meta.configurado():\n        raise HTTPException(status_code=400, detail="WhatsApp Business (Meta) todavía no está configurado en el servidor.")\n    return _whatsapp_bienvenida(usuario, cliente)\n\n\n@app.post("/api/cotizaciones/{cotizacion_id}/whatsapp")\ndef api_cotizacion_whatsapp_automatico(cotizacion_id: int, usuario: dict = Depends(requiere_ver_checador_precio)):\n    """Manda al cliente, por la API de Meta, la plantilla de bienvenida con\n    el PDF de la cotización adjunto. Si el teléfono no es de un cliente del\n    CRM todavía, lo da de alta (prospecto) y liga la cotización."""\n    empresa_id = usuario["empresa_id"]\n    cotizacion = db.obtener_cotizacion(empresa_id, cotizacion_id)\n    if not cotizacion:\n        raise HTTPException(status_code=404, detail="Cotización no encontrada")\n    if usuario["rol"] == "usuario" and cotizacion["creado_por_id"] != usuario["id"]:\n        raise HTTPException(status_code=403, detail="No puedes enviar esta cotización")\n    if not whatsapp_meta.configurado():\n        raise HTTPException(status_code=400, detail="WhatsApp Business (Meta) todavía no está configurado en el servidor.")\n    telefono = (cotizacion.get("cliente_telefono") or "").strip()\n    if not whatsapp_meta.normalizar_telefono(telefono):\n        raise HTTPException(status_code=400, detail="La cotización no tiene un teléfono válido del cliente (10 dígitos).")\n\n    cliente_id = cotizacion.get("cliente_crm_id")\n    if not cliente_id:\n        cliente = db.buscar_cliente_crm_por_ultimos10(empresa_id, whatsapp_meta.ultimos_10(telefono))\n        if not cliente:\n            nuevo_id = db.crear_cliente_crm(empresa_id, cotizacion["cliente_nombre"], "prospecto", telefono,\n                                            None, cotizacion.get("cliente_direccion"), None, usuario["id"])\n            cliente = {"id": nuevo_id}\n        cliente_id = cliente["id"]\n        db.vincular_cotizacion_cliente_crm(empresa_id, cotizacion_id, cliente_id)\n\n    cotizacion["imagen_visual"] = db.obtener_imagen_visual_cotizacion(cotizacion_id)\n    empresa = db.obtener_empresa(empresa_id) or {}\n    diseno = db.obtener_plantilla_pdf(empresa_id, "cotizacion")\n    pdf_bytes = pdfs_cotizaciones.generar_cotizacion_pdf(cotizacion, empresa, diseno)\n    total_texto = f"${float(cotizacion.get(\'total\') or 0):,.2f}"\n    try:\n        wamid = whatsapp_meta.enviar_cotizacion(\n            telefono, cotizacion["cliente_nombre"], empresa.get("nombre") or "nuestra empresa", cotizacion["folio"],\n            total_texto, usuario.get("nombre") or "tu asesor", pdf_bytes, f"Cotizacion_{cotizacion[\'folio\']}.pdf",\n        )\n    except whatsapp_meta.ErrorWhatsApp as e:\n        db.registrar_envio_whatsapp(empresa_id, "cotizacion", telefono, "error", usuario["id"], cliente_id,\n                                    cotizacion_id, error=str(e))\n        return {"ok": False, "estatus": "error", "error": str(e), "cliente_crm_id": cliente_id}\n    db.registrar_envio_whatsapp(empresa_id, "cotizacion", telefono, "sent", usuario["id"], cliente_id,\n                                cotizacion_id, wamid=wamid)\n    try:\n        db.crear_interaccion_crm(empresa_id, cliente_id, None, "whatsapp",\n                                 f"WhatsApp automático: cotización {cotizacion[\'folio\']} ({total_texto}) con PDF",\n                                 usuario["id"])\n    except Exception as e:\n        print(f"[whatsapp_meta] no se pudo registrar la interacción: {e}")\n    return {"ok": True, "estatus": "sent", "error": None, "cliente_crm_id": cliente_id}\n\n\n@app.get("/api/cotizaciones/{cotizacion_id}/whatsapp")\ndef api_cotizacion_whatsapp_estatus(cotizacion_id: int, usuario: dict = Depends(requiere_ver_checador_precio)):\n    cotizacion = db.obtener_cotizacion(usuario["empresa_id"], cotizacion_id)\n    if not cotizacion:\n        raise HTTPException(status_code=404, detail="Cotización no encontrada")\n    return db.ultimo_envio_whatsapp_cotizacion(cotizacion_id) or {}\n\n\n@app.get("/webhook/whatsapp-meta")\ndef webhook_whatsapp_meta_verificar(request: Request):\n    """Meta llama aquí (GET) una sola vez al configurar el webhook."""\n    q = request.query_params\n    reto = whatsapp_meta.verificar_suscripcion(q.get("hub.mode"), q.get("hub.verify_token"), q.get("hub.challenge"))\n    if reto is None:\n        raise HTTPException(status_code=403, detail="Token de verificación incorrecto")\n    return Response(content=reto, media_type="text/plain")\n\n\n@app.post("/webhook/whatsapp-meta")\nasync def webhook_whatsapp_meta(request: Request):\n    """Avisos de Meta: estatus de los mensajes (entregado, leído, falló) y\n    mensajes que nos contestan los clientes (quedan en el historial del CRM).\n    Sin login (Meta no manda tu JWT); se valida con la firma si hay\n    WHATSAPP_META_APP_SECRET. Siempre responde 200 para que Meta no reintente."""\n    cuerpo = await request.body()\n    if not whatsapp_meta.firma_valida(cuerpo, request.headers.get("x-hub-signature-256")):\n        raise HTTPException(status_code=403, detail="Firma inválida")\n    try:\n        estatus, mensajes = whatsapp_meta.extraer_eventos(json.loads(cuerpo or b"{}"))\n        for s in estatus:\n            db.actualizar_envio_whatsapp_por_wamid(s["wamid"], s["estatus"], s["error"])\n        for m in mensajes:\n            ult10 = whatsapp_meta.ultimos_10(m["telefono"])\n            ref = db.empresa_de_ultimo_envio_whatsapp(ult10)\n            if not ref:\n                continue\n            cliente = db.buscar_cliente_crm_por_ultimos10(ref["empresa_id"], ult10)\n            if cliente:\n                db.crear_interaccion_crm(ref["empresa_id"], cliente["id"], None, "whatsapp",\n                                         f"Cliente respondió: {m[\'texto\']}", None)\n    except Exception as e:\n        print(f"[whatsapp_meta] error procesando webhook: {e}")\n    return {"ok": True}\n\n\n@app.put("/api/cotizaciones/{cotizacion_id}")']]}

NUEVOS = {'backend/whatsapp_meta.py': '"""WhatsApp Business — API oficial de Meta (Cloud API), directo, sin Twilio.\n\nSe usa para los mensajes AUTOMÁTICOS a clientes desde ventas (app de iPad\n"Markinc Ventas" y el Checador de precio):\n  - bienvenida al dar de alta un cliente\n  - bienvenida + PDF de la cotización al crearla\n\nPor reglas de Meta, un mensaje que inicia la EMPRESA (el cliente no nos\nescribió en las últimas 24 h) solo puede ir como PLANTILLA aprobada en\nWhatsApp Manager. Por eso aquí todo se manda como plantilla.\n\nVariables de entorno (en Render):\n  WHATSAPP_META_TOKEN               token permanente del "usuario del sistema"\n  WHATSAPP_META_PHONE_NUMBER_ID     ID del número (no es el teléfono, es el ID que da Meta)\n  WHATSAPP_META_PLANTILLA_BIENVENIDA  nombre de la plantilla (default: bienvenida_cliente)\n  WHATSAPP_META_PLANTILLA_COTIZACION  nombre de la plantilla (default: cotizacion_cliente)\n  WHATSAPP_META_IDIOMA              código de idioma de las plantillas (default: es_MX)\n  WHATSAPP_META_VERIFY_TOKEN        texto que tú inventas, para validar el webhook\n  WHATSAPP_META_APP_SECRET          opcional: "Clave secreta de la app" para validar\n                                    que los avisos del webhook sí vienen de Meta\n\nPlantillas (crearlas así en WhatsApp Manager, idioma Español (MEX)):\n  bienvenida_cliente  (Marketing)\n    Cuerpo: Hola {{1}}, gracias por tu interés en {{2}}. Soy {{3}} y quedo a\n            tus órdenes. Por este medio te enviaremos tus cotizaciones y la\n            información de tus equipos.\n  cotizacion_cliente  (Utilidad) — Encabezado: Documento\n    Cuerpo: Hola {{1}}, gracias por tu interés en {{2}}. Te compartimos tu\n            cotización {{3}} por un total de {{4}} (IVA incluido). Cualquier\n            duda, responde a este mensaje; te atiende {{5}}.\n"""\nimport hashlib\nimport hmac\nimport os\nimport re\n\nimport requests\n\nGRAPH_URL = os.getenv("WHATSAPP_META_GRAPH_URL", "https://graph.facebook.com/v23.0").rstrip("/")\nTIMEOUT = 25\n\n\nclass ErrorWhatsApp(Exception):\n    """Error con mensaje entendible para el vendedor."""\n\n\ndef _cfg():\n    return {\n        "token": os.getenv("WHATSAPP_META_TOKEN", "").strip(),\n        "phone_id": os.getenv("WHATSAPP_META_PHONE_NUMBER_ID", "").strip(),\n        "pl_bienvenida": os.getenv("WHATSAPP_META_PLANTILLA_BIENVENIDA", "").strip() or "bienvenida_cliente",\n        "pl_cotizacion": os.getenv("WHATSAPP_META_PLANTILLA_COTIZACION", "").strip() or "cotizacion_cliente",\n        "idioma": os.getenv("WHATSAPP_META_IDIOMA", "").strip() or "es_MX",\n    }\n\n\ndef configurado() -> bool:\n    c = _cfg()\n    return bool(c["token"] and c["phone_id"])\n\n\ndef normalizar_telefono(telefono) -> str | None:\n    """Deja el número como lo pide Meta: solo dígitos con lada de país.\n    10 dígitos → México (52). Quita el \'1\' viejo de celulares mexicanos\n    (521XXXXXXXXXX → 52XXXXXXXXXX)."""\n    d = re.sub(r"\\D", "", str(telefono or ""))\n    if d.startswith("00"):\n        d = d[2:]\n    if len(d) == 10:\n        return "52" + d\n    if len(d) == 13 and d.startswith("521"):\n        return "52" + d[3:]\n    if len(d) == 12 and d.startswith("52"):\n        return d\n    if 11 <= len(d) <= 15 and not d.startswith("52"):\n        return d\n    return None\n\n\ndef ultimos_10(telefono) -> str:\n    d = re.sub(r"\\D", "", str(telefono or ""))\n    return d[-10:]\n\n\ndef _texto_param(valor, maximo=200) -> str:\n    """Meta rechaza parámetros con saltos de línea, tabs o 4+ espacios seguidos."""\n    t = re.sub(r"[\\r\\n\\t]+", " ", str(valor if valor is not None else "")).strip()\n    t = re.sub(r" {2,}", " ", t)\n    return (t or "-")[:maximo]\n\n\n_ERRORES_CONOCIDOS = {\n    131026: "Ese número no tiene WhatsApp o no puede recibir mensajes.",\n    131030: "Ese número no está en la lista de prueba de Meta (en modo prueba solo llega a números agregados).",\n    132000: "La plantilla no tiene los datos que espera — revisa que tenga las variables {{1}}…{{n}} correctas.",\n    132001: "La plantilla no existe o todavía no está aprobada en ese idioma.",\n    132005: "Algún dato de la plantilla es demasiado largo.",\n    132012: "Los datos no coinciden con el formato de la plantilla (por ejemplo, falta el encabezado de Documento).",\n    131047: "Ya pasaron más de 24 h desde que el cliente escribió — solo se puede mandar con plantilla.",\n    131056: "Se mandaron demasiados mensajes a ese número en poco tiempo; intenta en unos minutos.",\n    130429: "Se alcanzó el límite de envíos de Meta; intenta en unos minutos.",\n    131031: "La cuenta de WhatsApp Business está bloqueada o restringida por Meta.",\n    190: "El token de Meta venció o es inválido — genera uno permanente del usuario del sistema.",\n    100: "Meta rechazó la solicitud (revisa el ID del número y la configuración).",\n}\n\n\ndef _error_de_respuesta(resp) -> ErrorWhatsApp:\n    try:\n        err = (resp.json() or {}).get("error") or {}\n    except Exception:\n        err = {}\n    codigo = err.get("code")\n    detalle = ((err.get("error_data") or {}).get("details") or err.get("message") or resp.text or "")[:300]\n    amigable = _ERRORES_CONOCIDOS.get(codigo)\n    if amigable:\n        return ErrorWhatsApp(f"{amigable} (Meta {codigo})")\n    return ErrorWhatsApp(f"Meta respondió {resp.status_code}: {detalle}")\n\n\ndef _headers():\n    return {"Authorization": f"Bearer {_cfg()[\'token\']}"}\n\n\ndef subir_pdf(pdf_bytes: bytes, nombre_archivo: str) -> str:\n    """Sube el PDF a Meta y regresa el media_id (dura 30 días en Meta)."""\n    c = _cfg()\n    try:\n        resp = requests.post(\n            f"{GRAPH_URL}/{c[\'phone_id\']}/media",\n            headers=_headers(),\n            data={"messaging_product": "whatsapp", "type": "application/pdf"},\n            files={"file": (nombre_archivo, pdf_bytes, "application/pdf")},\n            timeout=TIMEOUT,\n        )\n    except requests.RequestException as e:\n        raise ErrorWhatsApp(f"No se pudo conectar con WhatsApp (Meta): {e}")\n    if resp.status_code >= 400:\n        raise _error_de_respuesta(resp)\n    media_id = (resp.json() or {}).get("id")\n    if not media_id:\n        raise ErrorWhatsApp("Meta no regresó el ID del PDF subido.")\n    return media_id\n\n\ndef enviar_plantilla(telefono: str, plantilla: str, parametros_cuerpo: list, documento: dict | None = None) -> str:\n    """Manda una plantilla. Regresa el wamid (ID del mensaje en Meta)."""\n    if not configurado():\n        raise ErrorWhatsApp("WhatsApp Business (Meta) no está configurado en el servidor.")\n    numero = normalizar_telefono(telefono)\n    if not numero:\n        raise ErrorWhatsApp("El teléfono no es válido — captura los 10 dígitos.")\n    c = _cfg()\n    componentes = []\n    if documento:\n        componentes.append({"type": "header", "parameters": [{"type": "document", "document": documento}]})\n    if parametros_cuerpo:\n        componentes.append({"type": "body", "parameters": [{"type": "text", "text": _texto_param(p)} for p in parametros_cuerpo]})\n    cuerpo = {\n        "messaging_product": "whatsapp",\n        "to": numero,\n        "type": "template",\n        "template": {"name": plantilla, "language": {"code": c["idioma"]}, "components": componentes},\n    }\n    try:\n        resp = requests.post(f"{GRAPH_URL}/{c[\'phone_id\']}/messages", headers=_headers(), json=cuerpo, timeout=TIMEOUT)\n    except requests.RequestException as e:\n        raise ErrorWhatsApp(f"No se pudo conectar con WhatsApp (Meta): {e}")\n    if resp.status_code >= 400:\n        raise _error_de_respuesta(resp)\n    mensajes = (resp.json() or {}).get("messages") or []\n    return (mensajes[0] or {}).get("id") if mensajes else None\n\n\ndef enviar_bienvenida(telefono, nombre_cliente, nombre_empresa, nombre_vendedor) -> str:\n    return enviar_plantilla(telefono, _cfg()["pl_bienvenida"], [nombre_cliente, nombre_empresa, nombre_vendedor])\n\n\ndef enviar_cotizacion(telefono, nombre_cliente, nombre_empresa, folio, total_texto, nombre_vendedor,\n                      pdf_bytes: bytes, nombre_archivo: str) -> str:\n    media_id = subir_pdf(pdf_bytes, nombre_archivo)\n    return enviar_plantilla(\n        telefono, _cfg()["pl_cotizacion"],\n        [nombre_cliente, nombre_empresa, folio, total_texto, nombre_vendedor],\n        documento={"id": media_id, "filename": nombre_archivo},\n    )\n\n\n# ---- Webhook ----\n\ndef verificar_suscripcion(modo, token, reto):\n    """GET del webhook: Meta pregunta con hub.verify_token; si coincide, se\n    regresa hub.challenge tal cual."""\n    esperado = os.getenv("WHATSAPP_META_VERIFY_TOKEN", "").strip()\n    if modo == "subscribe" and esperado and token == esperado:\n        return reto\n    return None\n\n\ndef firma_valida(cuerpo: bytes, firma_header: str | None) -> bool:\n    secreto = os.getenv("WHATSAPP_META_APP_SECRET", "").strip()\n    if not secreto:\n        return True  # sin secreto configurado no se valida (igual se aceptan los avisos)\n    if not firma_header or not firma_header.startswith("sha256="):\n        return False\n    esperado = hmac.new(secreto.encode(), cuerpo, hashlib.sha256).hexdigest()\n    return hmac.compare_digest(esperado, firma_header.split("=", 1)[1])\n\n\ndef extraer_eventos(payload: dict):\n    """Del aviso de Meta saca (estatus, mensajes entrantes).\n    estatus: [{wamid, estatus, error}]   mensajes: [{telefono, nombre, texto}]"""\n    estatus, mensajes = [], []\n    for entry in (payload or {}).get("entry") or []:\n        for change in entry.get("changes") or []:\n            value = change.get("value") or {}\n            for s in value.get("statuses") or []:\n                errores = s.get("errors") or []\n                error = None\n                if errores:\n                    e = errores[0]\n                    error = _ERRORES_CONOCIDOS.get(e.get("code")) or ((e.get("error_data") or {}).get("details") or e.get("title") or e.get("message"))\n                estatus.append({"wamid": s.get("id"), "estatus": s.get("status"), "error": error})\n            nombres = {c.get("wa_id"): ((c.get("profile") or {}).get("name")) for c in value.get("contacts") or []}\n            for m in value.get("messages") or []:\n                tipo = m.get("type")\n                if tipo == "text":\n                    texto = (m.get("text") or {}).get("body") or ""\n                elif tipo == "button":\n                    texto = (m.get("button") or {}).get("text") or ""\n                else:\n                    texto = f"[{tipo}]"\n                mensajes.append({"telefono": m.get("from"), "nombre": nombres.get(m.get("from")), "texto": texto})\n    return estatus, mensajes\n'}


def main():
    errores = []
    cambios = {}
    for ruta, contenido in NUEVOS.items():
        if os.path.exists(ruta):
            with open(ruta, encoding="utf-8") as f:
                actual = f.read().replace("\r\n", "\n")
            if actual == contenido:
                continue
        cambios[ruta] = contenido
    for ruta, pares in ARCHIVOS.items():
        if not os.path.exists(ruta):
            errores.append(f"No encontre {ruta} -- corre el script desde la carpeta del repo.")
            continue
        with open(ruta, encoding="utf-8", newline="") as f:
            original = f.read()
        texto = original
        for i, (viejo, nuevo) in enumerate(pares, 1):
            # En Windows los archivos pueden tener saltos de linea CRLF.
            variantes = [(viejo, nuevo)]
            if "\n" in viejo:
                variantes.append((viejo.replace("\n", "\r\n"), nuevo.replace("\n", "\r\n")))
            if any(nv in texto for _, nv in variantes):
                continue  # ya aplicado
            elegido = None
            for vj, nv in variantes:
                if texto.count(vj) == 1:
                    elegido = (vj, nv)
                    break
            if not elegido:
                n = max(texto.count(vj) for vj, _ in variantes)
                errores.append(f"{ruta}: cambio #{i} -- el texto a reemplazar aparece {n} veces (se esperaba 1).")
                continue
            texto = texto.replace(elegido[0], elegido[1], 1)
        if texto != original:
            cambios[ruta] = texto
    if errores:
        print("NO se aplico nada:")
        for e in errores:
            print("  -", e)
        sys.exit(1)
    for ruta, texto in cambios.items():
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(texto)
        print("Actualizado:", ruta)
    if not cambios:
        print("Todo ya estaba aplicado, no hubo cambios.")
    else:
        print("Listo.")


if __name__ == "__main__":
    main()
